#!name=动画疯
#!desc=fmz200/wool_scripts · 某些APP要清除缓存或者重新安装拦截广告才会生效！
#!author=奶思

[MITM]
hostname = api.gamer.com.tw

[Rewrite]
request if ${url} ~= /^https?:\/\/api\.gamer\.com\.tw\/mobile_app\/anime\/v\d\/anime_get_question\.php/i then reject_dict(200)

[Script]
response if ${url} ~= /^https?:\/\/api\.gamer\.com\.tw\/mobile_app\/anime\/v\d\/(token|m3u8).php\?/i then script("https://raw.githubusercontent.com/NobyDa/Script/master/Bahamut/BahamutAnimeAds.js") with enable=${dshxfg_enable}, tag="动画疯", timeout=60, requires_body=true
